代码示例：
class Gregarious {
public:
    virtual void talk() {
        cout << "Gregarious says hi!" << endl;
    }
};

class Shy : public Gregarious {
protected:
    void talk() override {
        cout << "Shy reluctantly says hello." << endl;
    }
};

Shy myShy;
myShy.talk();             // 错误：尝试访问 protected 成员
Gregarious& ref { myShy };
ref.talk();               // 调用 Shy::talk()，输出 Shy reluctantly says hello.
